export function Banner({
  message = "{{message}}",
  tone = "{{tone}}",
  actionLabel = "{{actionLabel}}",
  dismissible = {{dismissible}},
}) {
  const palette = {
    neutral: { c: "#241430", icon: "i" },
    success: { c: "#216B45", icon: "✓" },
    warning: { c: "#8A5A08", icon: "!" },
    critical: { c: "#8C1F17", icon: "‼" },
  }[tone] ?? { c: "#241430", icon: "i" };
  return (
    <div role="region" aria-label="Site announcement" style={{ display: "flex", alignItems: "center", gap: 12,
      width: "100%", maxWidth: 640, boxSizing: "border-box", padding: "12px 16px", borderRadius: 8,
      background: palette.c, color: "#FAF7F2", font: "14px/1.4 system-ui, sans-serif" }}>
      <span aria-hidden="true" style={{ width: 18, height: 18, borderRadius: "50%", flexShrink: 0, background: "#FAF7F2",
        display: "grid", placeItems: "center", color: palette.c, fontSize: 11, fontWeight: 700 }}>{palette.icon}</span>
      <p style={{ flex: 1, margin: 0 }}>{message}</p>
      <a href="#" style={{ color: "#FAF7F2", fontWeight: 600, textDecoration: "underline", whiteSpace: "nowrap" }}>{actionLabel}</a>
      {dismissible && (
        <button type="button" aria-label="Dismiss announcement" style={{ border: "none", background: "transparent",
          color: "#FAF7F2", fontSize: 16, cursor: "pointer", padding: 2, borderRadius: 4 }}>×</button>
      )}
    </div>
  );
}
